"""Shared no-RCM force-position execution layer for Chapters 3 and 5.

This module is the adapter between the thesis experiment packages and the
stabilized ROS2 no-RCM controller.  It intentionally reuses two artifacts from
``src/ch3_controller/run_no_rcm.py`` / ``src/no_rcm``:

* ``ContinuousForceMarginFuzzyAlphaScheduler`` for the complete
  ``continuous_force_margin`` arbitration law.
* The precomputed Pareto gain table generated by ``run_no_rcm.py`` for the
  cooperative-game force-position controller.

Loading the saved gain table is the same online path used after
``run_no_rcm.py`` has precomputed gains.  When the ROS2 package is importable the
adapter delegates interpolation to ``CooperativeGameController`` itself; the
small local interpolation class remains only as a fallback for isolated Python
analysis environments.  This keeps quick Python comparisons, realistic-noise
simulations and Gazebo chapter experiments on the same execution-layer law.
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
import sys
from typing import Iterable, Optional

import numpy as np


WORKSPACE = Path("/home/liu/franka_ros2_ws")


DEFAULT_GAIN_TABLE_CANDIDATES = (
    WORKSPACE
    / "results/ch3_complete_comparison_20260702_200221/no_rcm_continuous_force_margin/coop_gains_no_rcm_pareto_iter.npy",
    WORKSPACE
    / "results/ch3_ch4_ch5_unified_gazebo_20260702_051649/ch3_no_rcm_continuous/coop_gains_no_rcm_pareto_iter.npy",
    WORKSPACE
    / "real_env_sim_data_code_docs_20260703_061210/real/results/coop_gains_no_rcm_pareto_iter.npy",
)


def _ensure_no_rcm_import_paths() -> None:
    """Expose source-tree no_rcm helper modules to absolute legacy imports."""

    candidates = (
        WORKSPACE / "src/no_rcm",
        WORKSPACE / "src/no_rcm/no_rcm",
        WORKSPACE / "src/ch3_controller",
    )
    for path in candidates:
        s = str(path)
        if path.exists() and s not in sys.path:
            sys.path.insert(0, s)


def _load_scheduler_class():
    _ensure_no_rcm_import_paths()
    try:
        from no_rcm.src.alpha_scheduler_gt import ContinuousForceMarginFuzzyAlphaScheduler
    except Exception:
        from src.alpha_scheduler_gt import ContinuousForceMarginFuzzyAlphaScheduler
    return ContinuousForceMarginFuzzyAlphaScheduler


def _load_gt_controller_class():
    _ensure_no_rcm_import_paths()
    try:
        from no_rcm.src.gt_controller import CooperativeGameController
    except Exception:
        from src.gt_controller import CooperativeGameController
    return CooperativeGameController


class PrecomputedNoRcmGainTable:
    """Runtime interpolation over a saved no-RCM cooperative-game gain table."""

    def __init__(self, gain_table_path: Optional[str | Path] = None):
        path = self._resolve_path(gain_table_path)
        data = np.load(path, allow_pickle=True).item()
        self.path = Path(path)
        self.gains_db = data.get("gains_db", {})
        self.alpha_grid = np.asarray(data["alpha_grid"], dtype=float)
        self.Ke_grid = np.asarray(data["Ke_grid"], dtype=float)
        self.controller = None
        try:
            Controller = _load_gt_controller_class()
            self.controller = Controller(control_mode="pareto_iter")
            self.controller.load_gains(str(path))
            self.gains_db = self.controller.gains_db
            self.alpha_grid = np.asarray(self.controller.alpha_grid, dtype=float)
            self.Ke_grid = np.asarray(self.controller.Ke_grid, dtype=float)
        except Exception:
            self.controller = None
        if not self.gains_db:
            raise RuntimeError(f"empty no-RCM gain table: {path}")

    @staticmethod
    def _resolve_path(path: Optional[str | Path]) -> Path:
        if path is not None:
            p = Path(path)
            if p.exists():
                return p
            raise FileNotFoundError(f"no-RCM gain table not found: {p}")
        for candidate in DEFAULT_GAIN_TABLE_CANDIDATES:
            if candidate.exists():
                return candidate
        raise FileNotFoundError(
            "No precomputed no-RCM Pareto gain table found. Expected one of: "
            + ", ".join(str(p) for p in DEFAULT_GAIN_TABLE_CANDIDATES)
        )

    @staticmethod
    def _bracket(grid: Iterable[float], value: float):
        grid = np.asarray(list(grid), dtype=float)
        value = float(value)
        if value <= grid[0]:
            return grid[0], grid[0], 0.0
        if value >= grid[-1]:
            return grid[-1], grid[-1], 0.0
        idx = int(np.searchsorted(grid, value, side="right") - 1)
        idx = int(np.clip(idx, 0, len(grid) - 2))
        lo = grid[idx]
        hi = grid[idx + 1]
        t = (value - lo) / max(hi - lo, 1e-12)
        return lo, hi, float(t)

    def _get(self, alpha_key: float, K_key: int) -> np.ndarray:
        key = (round(float(alpha_key), 3), int(K_key))
        if key in self.gains_db:
            return np.asarray(self.gains_db[key], dtype=float)
        nearest = min(
            self.gains_db.keys(),
            key=lambda k: abs(float(k[0]) - key[0]) + abs(float(k[1]) - key[1]) / 1000.0,
        )
        return np.asarray(self.gains_db[nearest], dtype=float)

    def get_gain(self, alpha: float, K_e: float) -> np.ndarray:
        """Bilinear interpolation, matching ``gt_controller.get_gain``."""

        if self.controller is not None:
            return np.asarray(self.controller.get_gain(alpha, K_e), dtype=float)
        a_lo, a_hi, t_a = self._bracket(self.alpha_grid, float(np.clip(alpha, 0.0, 1.0)))
        k_lo, k_hi, t_k = self._bracket(self.Ke_grid, float(K_e))
        a_lo = round(float(a_lo), 3)
        a_hi = round(float(a_hi), 3)
        k_lo = int(k_lo)
        k_hi = int(k_hi)
        k00 = self._get(a_lo, k_lo)
        k01 = self._get(a_lo, k_hi)
        k10 = self._get(a_hi, k_lo)
        k11 = self._get(a_hi, k_hi)
        return (
            (1.0 - t_a) * (1.0 - t_k) * k00
            + (1.0 - t_a) * t_k * k01
            + t_a * (1.0 - t_k) * k10
            + t_a * t_k * k11
        )

    def compute_control_axis_alpha(
        self,
        e_r1: np.ndarray,
        e_r2: np.ndarray,
        e_f: np.ndarray,
        sigma_f: np.ndarray,
        alpha_xyz: np.ndarray,
        K_e: float,
    ):
        """Same online law as no-RCM ``compute_control_axis_alpha``."""

        e_r1 = np.asarray(e_r1, dtype=float).reshape(3)
        e_r2 = np.asarray(e_r2, dtype=float).reshape(3)
        e_f = np.asarray(e_f, dtype=float).reshape(3)
        sigma_f = np.asarray(sigma_f, dtype=float).reshape(3)
        alpha_xyz = np.asarray(alpha_xyz, dtype=float).reshape(3)
        if self.controller is not None:
            return self.controller.compute_control_axis_alpha(
                e_r1, e_r2, e_f, sigma_f, alpha_xyz, K_e
            )
        K_axes = np.vstack([self.get_gain(a, K_e) for a in alpha_xyz])
        u = -(
            K_axes[:, 0] * e_r1
            + K_axes[:, 1] * e_r2
            + K_axes[:, 2] * e_f
            + K_axes[:, 3] * sigma_f
        )
        return u, K_axes


@dataclass
class NoRcmExecutionOutput:
    """Single-step output from the no-RCM force-position execution adapter."""

    u: np.ndarray
    alpha: float
    alpha_target: float
    sigma_f: np.ndarray
    K_axes: np.ndarray
    rho_f: float
    s_f: float
    e_f_scalar: float
    e_r_alpha: float
    dK: float
    debug: dict


class NoRcmContinuousForceMarginExecution:
    """Complete continuous-force-margin execution layer used as "our method"."""

    def __init__(
        self,
        dt: float,
        force_desired: float,
        force_min: float,
        force_max: float,
        gain_table_path: Optional[str | Path] = None,
        force_axis: int = 2,
        control_scale: float = 1.0,
        output_limit: float = 60.0,
        stiffness_profile: str = "stable",
        fixed_alpha: Optional[float] = None,
    ):
        self.dt = float(dt)
        self.force_desired = float(force_desired)
        self.force_min = float(force_min)
        self.force_max = float(force_max)
        self.force_axis = int(force_axis)
        self.control_scale = float(control_scale)
        self.output_limit = float(output_limit)
        self.stiffness_profile = str(stiffness_profile or "stable")
        self.fixed_alpha = None if fixed_alpha is None else float(np.clip(fixed_alpha, 0.0, 1.0))
        Scheduler = _load_scheduler_class()
        scheduler_kwargs = self._scheduler_kwargs(self.stiffness_profile)
        self.scheduler = Scheduler(
            dt=self.dt,
            F_min=self.force_min,
            F_max=self.force_max,
            F_desired=self.force_desired,
            **scheduler_kwargs,
        )
        self.gains = PrecomputedNoRcmGainTable(gain_table_path)
        self.sigma_f = np.zeros(3, dtype=float)
        self.prev_e_f = 0.0
        self.prev_e_r = 0.0
        self.prev_K = 400.0
        self.last_alpha = 0.5
        self.last_alpha_target = 0.5

    @staticmethod
    def _scheduler_kwargs(profile: str) -> dict:
        """Return run_no_rcm-compatible scheduler parameters.

        ``stable`` is the controller used for the main chapter experiments.  It
        keeps the exact conservative values from ``run_no_rcm.py`` to avoid
        disturbing the already validated Gazebo runs.

        ``stiffness_sensitive`` is used only for alpha-law validation figures:
        it keeps the same force-margin structure but compresses the stiffness
        thresholds to the realistic Gazebo range and shortens the smoothing time
        constant, so the reported alpha visibly follows stiffness changes while
        staying bounded by the same force-safety guard.
        """

        stable = {
            "safe_tracking_alpha": 0.46,
            "safe_tracking_extra": 0.03,
            "force_balance_alpha": 0.46,
            "force_guard_alpha": 0.66,
            "low_force_guard_alpha": 0.34,
            "alpha_min": 0.30,
            "alpha_max": 0.74,
            "risk_margin_start": 0.20,
            "risk_margin_full": 0.04,
            "smooth_tau": 0.80,
            "stiffness_alpha_enabled": True,
            "stiffness_low_threshold": 300.0,
            "stiffness_high_threshold": 500.0,
            "stiffness_low_alpha": 0.42,
            "stiffness_high_alpha": 0.66,
            "stiffness_blend": 0.88,
            "stiffness_transition_alpha": 0.56,
            "stiffness_transition_dk_start": 12.0,
            "stiffness_transition_dk_full": 90.0,
            "stiffness_low_force_relief": 0.06,
            "stiffness_high_force_guard": 0.04,
        }
        if profile in ("stable", "", None):
            return stable
        if profile in ("stiffness_sensitive", "sensitive", "alpha_stiffness"):
            sensitive = dict(stable)
            sensitive.update(
                {
                    "safe_tracking_alpha": 0.42,
                    "safe_tracking_extra": 0.04,
                    "force_balance_alpha": 0.42,
                    "force_guard_alpha": 0.70,
                    "low_force_guard_alpha": 0.28,
                    "alpha_min": 0.24,
                    "alpha_max": 0.78,
                    "risk_margin_start": 0.18,
                    "risk_margin_full": 0.04,
                    "smooth_tau": 0.20,
                    "stiffness_low_threshold": 300.0,
                    "stiffness_high_threshold": 600.0,
                    "stiffness_low_alpha": 0.36,
                    "stiffness_high_alpha": 0.74,
                    "stiffness_blend": 1.0,
                    "stiffness_transition_alpha": 0.68,
                    "stiffness_transition_dk_start": 8.0,
                    "stiffness_transition_dk_full": 60.0,
                    "stiffness_low_force_relief": 0.0,
                    "stiffness_high_force_guard": 0.0,
                }
            )
            return sensitive
        if profile in ("rcm_sensitive", "with_rcm", "rcm"):
            rcm = dict(stable)
            rcm.update(
                {
                    "safe_tracking_alpha": 0.34,
                    "safe_tracking_extra": 0.02,
                    "force_balance_alpha": 0.34,
                    "force_guard_alpha": 0.76,
                    "low_force_guard_alpha": 0.22,
                    "alpha_min": 0.18,
                    "alpha_max": 0.72,
                    "risk_margin_start": 0.24,
                    "risk_margin_full": 0.06,
                    "smooth_tau": 0.16,
                    "stiffness_low_threshold": 300.0,
                    "stiffness_high_threshold": 600.0,
                    "stiffness_low_alpha": 0.30,
                    "stiffness_high_alpha": 0.58,
                    "stiffness_blend": 0.90,
                    "stiffness_transition_alpha": 0.62,
                    "stiffness_transition_dk_start": 6.0,
                    "stiffness_transition_dk_full": 45.0,
                    "stiffness_low_force_relief": 0.03,
                    "stiffness_high_force_guard": 0.08,
                }
            )
            return rcm
        raise ValueError(f"unknown no-RCM stiffness alpha profile: {profile}")

    @property
    def gain_table_path(self) -> Path:
        return self.gains.path

    def reset(self) -> None:
        self.scheduler.reset()
        self.sigma_f[:] = 0.0
        self.prev_e_f = 0.0
        self.prev_e_r = 0.0
        self.prev_K = 400.0
        self.last_alpha = 0.5
        self.last_alpha_target = 0.5

    @staticmethod
    def force_safety_terms(force, force_desired, force_min, force_max):
        width = max(float(force_max) - float(force_min), 1e-9)
        half = max(0.5 * width, 1e-9)
        lower = float(force) - float(force_min)
        upper = float(force_max) - float(force)
        rho = float(np.clip(min(lower, upper) / half, 0.0, 1.0))
        signed = float(np.clip((float(force) - float(force_desired)) / half, -1.0, 1.0))
        return rho, signed

    @staticmethod
    def _smoothstep01(value: float) -> float:
        value = float(np.clip(value, 0.0, 1.0))
        return value * value * (3.0 - 2.0 * value)

    def _alpha_debug_terms(
        self,
        force_norm: float,
        e_f_scalar: float,
        K_hat: float,
        e_r_alpha: float,
        z_vel: float,
        dK: float,
        tracking_boost_enabled: bool,
    ) -> dict:
        """Recompute non-state-changing alpha-law terms for logging only."""

        scheduler = self.scheduler
        F_h, S_h, D_r, rho_F, s_F, F_err = scheduler._force_margin_inputs(
            abs(float(force_norm)),
            self.force_desired,
            self.force_min,
            self.force_max,
            e_r_alpha,
        )
        alpha_fuzzy = scheduler._defuzzify_alpha(
            scheduler._infer(scheduler._fuzzify(F_h, S_h, D_r))
        )
        r_F = 1.0 - rho_F
        alpha_margin = (
            alpha_fuzzy
            + scheduler.k_upper * r_F * max(s_F, 0.0)
            - scheduler.k_lower * r_F * max(-s_F, 0.0)
        )

        alpha_after_tracking = float(alpha_margin)
        if (
            abs(float(force_norm)) < self.force_max
            and abs(float(force_norm)) > self.force_min
            and tracking_boost_enabled
        ):
            alpha_after_tracking = scheduler._safe_tracking_boost(
                alpha_after_tracking, rho_F=rho_F, F_err=F_err, e_r=e_r_alpha
            )
        alpha_after_risk = scheduler._force_risk_rebalance(
            alpha_after_tracking, rho_F=rho_F, F_err=F_err
        )
        alpha_after_stiffness = scheduler._stiffness_rebalance(
            alpha_after_risk, K_hat, F_err=F_err, dK=dK
        )
        alpha_safe = float(np.clip(alpha_after_stiffness, scheduler.alpha_min, scheduler.alpha_max))

        phase_value = -1.0
        alpha_phi = np.nan
        w_phi = np.nan
        if getattr(scheduler, "phase_history", None):
            phase_value = float(scheduler.phase_history[-1])
        if getattr(scheduler, "phase_prior_history", None):
            alpha_phi, w_phi = scheduler.phase_prior_history[-1]
            alpha_phi = float(alpha_phi)
            w_phi = float(w_phi)
        alpha_raw_est = np.nan
        if np.isfinite(alpha_phi) and np.isfinite(w_phi):
            alpha_raw_est = float(np.clip(w_phi * alpha_phi + (1.0 - w_phi) * alpha_safe, 0.01, 0.99))

        safe_margin_full = max(scheduler.safe_margin_full - scheduler.safe_margin_start, 1e-9)
        force_error_full = max(scheduler.force_error_full - scheduler.force_error_start, 1e-9)
        track_error_full = max(scheduler.track_error_full - scheduler.track_error_start, 1e-9)
        margin_gate = self._smoothstep01((rho_F - scheduler.safe_margin_start) / safe_margin_full)
        force_gate = 1.0 - self._smoothstep01((abs(F_err) - scheduler.force_error_start) / force_error_full)
        track_gate = self._smoothstep01((abs(e_r_alpha) - scheduler.track_error_start) / track_error_full)
        tracking_boost_gate = margin_gate * force_gate * track_gate

        risk_den = max(scheduler.risk_margin_start - scheduler.risk_margin_full, 1e-9)
        risk_margin_gate = 1.0 - self._smoothstep01((rho_F - scheduler.risk_margin_full) / risk_den)
        force_high_gate = self._smoothstep01(
            (F_err - scheduler.force_error_start)
            / max(scheduler.force_error_hard - scheduler.force_error_start, 1e-9)
        )
        force_low_gate = self._smoothstep01(
            (-F_err - scheduler.force_error_start)
            / max(scheduler.force_error_hard - scheduler.force_error_start, 1e-9)
        )

        if (
            scheduler.stiffness_alpha_enabled
            and scheduler.stiffness_blend > 1e-9
            and np.isfinite(K_hat)
        ):
            stiffness_gate = self._smoothstep01(
                (float(K_hat) - scheduler.stiffness_low_threshold)
                / max(scheduler.stiffness_high_threshold - scheduler.stiffness_low_threshold, 1e-9)
            )
            stiffness_transition_gate = self._smoothstep01(
                (abs(float(dK)) - scheduler.stiffness_transition_dk_start)
                / max(scheduler.stiffness_transition_dk_full - scheduler.stiffness_transition_dk_start, 1e-9)
            )
            stiffness_alpha_target = (
                (1.0 - stiffness_gate) * scheduler.stiffness_low_alpha
                + stiffness_gate * scheduler.stiffness_high_alpha
            )
        else:
            stiffness_gate = 0.0
            stiffness_transition_gate = 0.0
            stiffness_alpha_target = float(alpha_after_risk)

        return {
            "alpha_FP_fixed_mode": 0.0 if self.fixed_alpha is None else 1.0,
            "alpha_FP_phase": phase_value,
            "alpha_FP_phase_prior": alpha_phi,
            "alpha_FP_phase_weight": w_phi,
            "alpha_FP_fuzzy_base": float(alpha_fuzzy),
            "alpha_FP_after_margin": float(alpha_margin),
            "alpha_FP_after_tracking": float(alpha_after_tracking),
            "alpha_FP_after_force_risk": float(alpha_after_risk),
            "alpha_FP_stiffness_target": float(stiffness_alpha_target),
            "alpha_FP_after_stiffness": float(alpha_after_stiffness),
            "alpha_FP_safe_clipped": float(alpha_safe),
            "alpha_FP_raw_estimated": alpha_raw_est,
            "alpha_FP_margin_gate": float(margin_gate),
            "alpha_FP_force_gate": float(force_gate),
            "alpha_FP_track_gate": float(track_gate),
            "alpha_FP_tracking_boost_gate": float(tracking_boost_gate),
            "alpha_FP_risk_margin_gate": float(risk_margin_gate),
            "alpha_FP_force_high_gate": float(max(force_high_gate, risk_margin_gate if F_err > 0.0 else 0.0)),
            "alpha_FP_force_low_gate": float(max(force_low_gate, risk_margin_gate if F_err < 0.0 else 0.0)),
            "alpha_FP_stiffness_gate": float(stiffness_gate),
            "alpha_FP_stiffness_transition_gate": float(stiffness_transition_gate),
            "alpha_FP_F_h": float(F_h),
            "alpha_FP_S_h": float(S_h),
            "alpha_FP_D_r": float(D_r),
            "alpha_FP_rho_F": float(rho_F),
            "alpha_FP_s_F": float(s_F),
            "alpha_FP_force_error_N": float(F_err),
            "alpha_FP_K_hat": float(K_hat),
            "alpha_FP_dK": float(dK),
            "alpha_FP_e_r_normal_m": float(e_r_alpha),
            "alpha_FP_z_vel_mps": float(z_vel),
        }

    def compute(
        self,
        pos: np.ndarray,
        vel: np.ndarray,
        pos_ref: np.ndarray,
        vel_ref: np.ndarray,
        force_norm: float,
        K_hat: float,
        force_blend: float = 1.0,
        tracking_boost_enabled: bool = True,
    ) -> NoRcmExecutionOutput:
        pos = np.asarray(pos, dtype=float).reshape(3)
        vel = np.asarray(vel, dtype=float).reshape(3)
        pos_ref = np.asarray(pos_ref, dtype=float).reshape(3)
        vel_ref = np.asarray(vel_ref, dtype=float).reshape(3)
        e_r1 = pos - pos_ref
        e_r2 = vel - vel_ref
        e_f_vec = np.zeros(3, dtype=float)
        e_f_vec[self.force_axis] = float(force_norm) - self.force_desired
        e_f_vec *= float(np.clip(force_blend, 0.0, 1.0))
        self.sigma_f += self.dt * (e_f_vec - 2.0 * self.sigma_f)
        self.sigma_f = np.clip(self.sigma_f, -0.8, 0.8)

        e_f_scalar = float(e_f_vec[self.force_axis])
        e_f_dot = (e_f_scalar - self.prev_e_f) / max(self.dt, 1e-9)
        self.prev_e_f = e_f_scalar
        e_r_alpha = abs(float(e_r1[self.force_axis]))
        de_r = (e_r_alpha - self.prev_e_r) / max(self.dt, 1e-9)
        self.prev_e_r = e_r_alpha
        K_hat = float(np.clip(K_hat, 50.0, 5000.0))
        dK = (K_hat - self.prev_K) / max(self.dt, 1e-9)
        self.prev_K = K_hat

        if self.fixed_alpha is None:
            alpha = self.scheduler.compute(
                F_norm=abs(float(force_norm)),
                e_f=e_f_scalar,
                K_hat=K_hat,
                e_r=e_r_alpha,
                z_vel=float(vel[self.force_axis]),
                de_f=e_f_dot,
                dK=dK,
                de_r=de_r,
                F_desired=self.force_desired,
                F_min=self.force_min,
                F_max=self.force_max,
                tracking_boost_enabled=tracking_boost_enabled,
            )
        else:
            alpha = self.fixed_alpha
        alpha = float(np.clip(alpha, 0.0, 1.0))
        self.last_alpha = alpha
        self.last_alpha_target = alpha
        alpha_xyz = np.array([1.0, 1.0, alpha], dtype=float)
        u_game_raw, K_axes = self.gains.compute_control_axis_alpha(
            e_r1, e_r2, e_f_vec, self.sigma_f, alpha_xyz, K_hat
        )
        u_game_raw = self.control_scale * np.asarray(u_game_raw, dtype=float)
        u = u_game_raw.copy()
        u_tracking_boost = np.zeros(3, dtype=float)
        normal_gate = np.nan
        force_err_norm = min(abs(e_f_scalar) / max(self.force_max - self.force_min, 1e-9), 1.0)
        if tracking_boost_enabled:
            # The Pareto gain table comes from the stabilized no-RCM controller.
            # In Gazebo effort mode the raw table is slightly too soft for
            # smooth-letter scans and leaves a steady tangential lag.  Add a
            # bounded tracking envelope on top of the game-theoretic command:
            # tangential axes get position recovery, while the normal boost is
            # reduced when the force error grows so force regulation remains the
            # dominant safety mechanism.
            track_err = pos_ref - pos
            vel_track_err = vel_ref - vel
            normal_gate = (0.25 + 0.75 * alpha) * (1.0 - 0.65 * force_err_norm)
            normal_gate = float(np.clip(normal_gate, 0.15, 1.0))
            kp_boost = np.array([520.0, 520.0, 200.0 * normal_gate], dtype=float)
            kd_boost = np.array([115.0, 115.0, 58.0 * normal_gate], dtype=float)
            boost = kp_boost * track_err + kd_boost * vel_track_err
            # Keep this as a local stabilizing envelope, not a replacement for
            # continuous_force_margin.  The main command still comes from the
            # alpha-dependent cooperative-game gain table.
            u_tracking_boost = 0.85 * boost
            u += u_tracking_boost
        u_pre_limit = u.copy()
        norm = float(np.linalg.norm(u))
        output_limit_active = 0.0
        output_limit_scale = 1.0
        if self.output_limit > 0.0 and norm > self.output_limit:
            output_limit_active = 1.0
            output_limit_scale = self.output_limit / max(norm, 1e-12)
            u *= output_limit_scale
        rho_f, s_f = self.force_safety_terms(
            force_norm, self.force_desired, self.force_min, self.force_max
        )
        component_position = -self.control_scale * K_axes[:, 0] * e_r1
        component_velocity = -self.control_scale * K_axes[:, 1] * e_r2
        component_force = -self.control_scale * K_axes[:, 2] * e_f_vec
        component_sigma = -self.control_scale * K_axes[:, 3] * self.sigma_f
        debug = self._alpha_debug_terms(
            force_norm=force_norm,
            e_f_scalar=e_f_scalar,
            K_hat=K_hat,
            e_r_alpha=e_r_alpha,
            z_vel=float(vel[self.force_axis]),
            dK=dK,
            tracking_boost_enabled=tracking_boost_enabled,
        )
        debug.update(
            {
                "execution_e_r": e_r1.copy(),
                "execution_e_v": e_r2.copy(),
                "execution_e_f": e_f_vec.copy(),
                "execution_sigma_f": self.sigma_f.copy(),
                "execution_K_axes": K_axes.copy(),
                "execution_u_game_raw": u_game_raw.copy(),
                "execution_u_tracking_boost": u_tracking_boost.copy(),
                "execution_u_pre_limit": u_pre_limit.copy(),
                "execution_component_position": component_position.copy(),
                "execution_component_velocity": component_velocity.copy(),
                "execution_component_force": component_force.copy(),
                "execution_component_sigma": component_sigma.copy(),
                "execution_output_norm_pre_limit": norm,
                "execution_output_norm": float(np.linalg.norm(u)),
                "execution_output_limit": float(self.output_limit),
                "execution_output_limit_active": output_limit_active,
                "execution_output_limit_scale": output_limit_scale,
                "execution_normal_gate": float(normal_gate),
                "execution_force_error_norm": float(force_err_norm),
                "execution_tracking_boost_enabled": 1.0 if tracking_boost_enabled else 0.0,
            }
        )
        return NoRcmExecutionOutput(
            u=u,
            alpha=alpha,
            alpha_target=self.last_alpha_target,
            sigma_f=self.sigma_f.copy(),
            K_axes=K_axes,
            rho_f=rho_f,
            s_f=s_f,
            e_f_scalar=e_f_scalar,
            e_r_alpha=e_r_alpha,
            dK=dK,
            debug=debug,
        )
